#!/usr/bin/env python3
"""Build PSOP workspaces around a sourced Microduck identification and recheck example."""
from pathlib import Path
import json,xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'prototypes';ASSET='../assets/generated/microduck/'
ICONS={'cube':'M4 7 12 3 20 7v10l-8 4-8-4ZM4 7l8 4 8-4M12 11v10','folder':'M3 6h7l2 2h9v12H3Z','graph':'M3 4h6v6H3ZM15 14h6v6h-6ZM6 10v7h9M9 7h9v7','play':'m8 4 12 8-12 8Z','check':'m4 12 5 5L20 6','search':'M20 20l-5-5M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0','cross':'M4 12h16M12 4v16','file':'M5 3h9l5 5v13H5ZM14 3v6h5M8 13h8M8 17h6','camera':'M3 7h5l2-3h5l2 3h4v13H3ZM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0','chat':'M3 4h18v13H9l-6 4Z','layers':'m2 8 10-5 10 5-10 5ZM2 13l10 5 10-5M2 18l10 5 10-5','settings':'M4 5h16M4 12h16M4 19h16M8 2v6M16 9v6M10 16v6'}
def ico(n):return f'<svg class="ico" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.55" stroke-linecap="round" stroke-linejoin="round"><path d="{ICONS.get(n,ICONS["cube"])}"/></svg>'
def tag(s,c=''):return f'<span class="tag {c}">{s}</span>'
def button(s,cls='',act=None):return f'<button class="{cls}"'+(f' data-act="{act}"' if act else '')+f'>{s}</button>'
def tabs(items,active=0,tools=''):return '<div class="view-tabs">'+''.join(f'<span class="{"on" if i==active else ""}">{s}</span>' for i,s in enumerate(items))+'<span class="push"></span>'+tools+'</div>'
def row(k,v,cl=''):return f'<div class="prop"><span>{k}</span><b class="{cl}">{v}</b></div>'
def header(stage):
 title='髋部舵机安装与复检' if stage=='simulate' else '舵机更换后的软件识别与复检'
 nav=''.join(f'<a class="{"active" if s==stage else ""}" href="{s}.html">{ico(i)}{s}</a>' for s,i in [('build','cube'),('compile','graph'),('simulate','play')])
 return f'<header><div class="brand">{ico("cube")}PSOP <small>STUDIO</small></div><nav>{nav}</nav><div class="search">{ico("search")}搜索工程对象 <kbd>⌘ K</kbd></div><a class="mobile-link" href="mobile.html">移动端 ↗</a><span class="user">YL</span></header><div class="projectbar"><span class="muted">设备服务 / Microduck /</span><b>{title}</b>{tag("MD-01")}<span class="push"></span><span class="saved">● 本地场景</span><span class="draft">工程交互设计原型</span>{button("任务包 Rev.A","primary")}</div>'
def rail(stage):return '<div class="rail">'+''.join(f'<div class="{"selected" if s==stage else ""}">{ico(i)}</div>' for s,i in [('build','cube'),('files','folder'),('compile','graph'),('simulate','play')])+'<span class="push"></span><div>'+ico('settings')+'</div></div>'
def tree(stage):
 rows=[('▾','Microduck 整机','MD-01',''),('◇','设备配置与任务对象','MD-01','selected' if stage=='build' else 'indent'),('◇','关节系统与通信','JOINTS-01','indent'),('◇','头部与相机观察','HEAD-01','indent'),('◇','目标关节：左髋偏航','J01','indent'),('▾','任务证据','OBSERVATIONS',''),('◇','S03 身份识别记录','IDENTITY-01','indent'),('◇','J01 复检记录待补齐','J01','selected' if stage=='simulate' else 'indent')]
 if stage=='compile':rows=[('▾','识别与复检任务','MD-SERVO-CHECK-01',''),('○','设备与步骤绑定','P01 / P02','indent'),('▮','并行取证','T02','indent'),('○','身份识别记录','P06','indent'),('○','复检待确认','P05','selected'),('▮','复检记录','T04','indent'),('▮','检查推进条件','T05','indent'),('○','进入下一步骤','P08','indent')]
 r=''.join(f'<div class="tree-row {cl}" data-select="{id}"><span class="tree-symbol">{sym}</span><span>{lab}<small>{id}</small></span><span class="tree-eye">◉</span></div>' for sym,lab,id,cl in rows)
 return f'<aside class="tree"><div class="panel-heading">{"EG 任务结构" if stage=="compile" else "工程对象与观察"}<span>•••</span></div><div class="filter">{ico("search")}按名称或特征编号筛选</div><div class="tree-root">MD-01 / 官方 alpha 配置<span>⌄</span></div>{r}<div class="tree-section">关联工程资料 <span>＋</span></div><div class="document">{ico("file")}设备说明与关节表 <small>Rev.A</small></div><div class="document">{ico("file")}官方故障排查与软件说明 <small>REF</small></div><div class="tree-bottom">当前任务<br><b>MD-SERVO-CHECK-01 / STEP S03</b></div></aside>'
def footer():return '<footer><span><i></i> 本地设计空间</span><span>MD-01 · MD-SERVO-CHECK-01 Rev.A</span><span class="push"></span><span>walk 来源外形 / 合成任务记录 · 未连接实机控制</span></footer>'
def doc(body,stage):
 extra_style='<link rel="stylesheet" href="simulator.css">' if stage=='simulate' else ''
 scripts=('<script src="vendor/three.min.js"></script><script src="microduck-source.js"></script><script src="microduck-model.js"></script><script src="'+('build-knowledge.js' if stage=='build' else 'engineering-sandbox.js')+'"></script>') if stage in ('build','simulate') else ''
 return f'<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PSOP {stage} · 工程设计原型</title><link rel="stylesheet" href="workbench.css"><link rel="stylesheet" href="engineering.css">{extra_style}</head><body>{body}{scripts}</body></html>'
def app(stage,body):return doc(f'<div class="app psop-app">{header(stage)}<div class="workspace">{rail(stage)}{body}</div>{footer()}</div>',stage)
def scene(stage):
 if stage=='build':
  tools=''.join(button(s,act=a) for s,a in [('爆炸展开','explode'),('剖切','section'),('旋转','orbit'),('重置','reset')])
  return '<div class="stage3d build-knowledge-view" data-mode="build"><div class="scene-toolbar">'+tools+'<span>walk 来源外形 / alpha 知识另核对</span></div><div class="scene-caption">MD-01 <small>设备对象 · 部件与来源关系</small></div><div class="knowledge-legend"><span><i class="feature-dot"></i>设备部件</span><span><i class="knowledge-dot"></i>关联知识</span><span><i class="review-dot"></i>待校核</span></div><div class="scene-status">拖动旋转 · 点击特征查看关联知识</div><span class="model-units">SOURCE MODEL</span></div>'
def build():
 center='<main class="center">'+tabs(['工程对象','设备配置','操作与复检依据'],tools=button('MD-01 / alpha'))+scene('build')+'<div class="bottom-drawer"><div class="drawer-title"><b>设备部件关联配置、操作和验证依据</b><span class="push"></span><small>部件知识 → 任务条件</small></div><div class="constraint-strip"><div><b>工程对象</b><span id="knowledge-object">设备配置与任务对象</span></div><div><b>关联关系</b><span id="knowledge-relations">包含 · 使用</span></div><div><b>官方来源</b><span id="knowledge-evidence">官方设备资料 / alpha 配置</span></div></div></div></main>'
 props=''.join('<div class="prop"><span data-feature-label="'+str(i)+'">'+k+'</span><b data-feature-value="'+str(i)+'">'+v+'</b></div>' for i,(k,v) in enumerate([('设备类型','小型双足机器人'),('计算平台','Radxa Zero 3W'),('电池','NP-F550'),('任务版本','Rev.A')]))
 inspect='<aside class="inspector build-inspector"><div class="panel-heading">特征与关联知识<span>•••</span></div>'+tabs(['参数','关系','依据'])+'<div class="inspector-body"><div class="eyebrow">FEATURE / KNOWLEDGE</div><h2 id="feature-title">设备配置与任务对象</h2><div class="object-id" id="selected-feature">MD-01</div>'+props+'<div class="rule"></div><h4>关联知识</h4><div id="feature-relations" class="feature-relations"><div><span>包含</span><b>头部、躯干与双腿</b></div><div><span>使用</span><b>官方 alpha 软件配置</b></div></div><div class="feature-review" id="feature-review">设备版本需与具体实机核对</div><h4>依据与验证</h4><div class="task-link">'+ico('file')+'<div id="feature-evidence">官方设备资料 / alpha 配置<small>官方固定版本 / 本地知识包整理</small></div></div><p class="subtle">38 个官方 STL / 70 个实例；walk 外形与 alpha 软件配置需分别核对。</p><a class="primary-link" href="compile.html">组织身份识别与复检任务 →</a></div></aside>'
 return app('build',tree('build')+center+inspect)

def cpn():
 ps=[('p_task',76,86,'识别任务已加载','#338fbe',False),('p_cell',76,275,'设备已关联','#51a396',True),('p_bound',324,180,'S03 已绑定','#338fbe',False),('p_config',518,86,'身份待核验','#338fbe',False),('p_cal',518,275,'复检待确认','#b88a40',True),('p_configok',740,86,'身份记录已核验','#51a396',True),('p_calok',740,275,'复检记录已核验','#b88a40',False),('p_ready',953,180,'推进条件齐备','#8b7fc1',False)]
 ts=[('t_load',206,153,'绑定设备与步骤'),('t_split',410,153,'并行取证'),('t_config',620,59,'核验舵机身份'),('t_cal',620,248,'复检记录'),('t_join',841,153,'检查推进条件')]
 arcs=[('p_task','t_load','M104 86C158 86 154 163 206 173'),('p_cell','t_load','M104 275C162 275 156 195 206 186'),('t_load','p_bound','M224 180H296'),('p_bound','t_split','M352 180H410'),('t_split','p_config','M428 170C463 170 460 86 490 86'),('t_split','p_cal','M428 190C463 190 460 275 490 275'),('p_config','t_config','M546 86H620'),('p_cal','t_cal','M546 275H620'),('t_config','p_configok','M638 86H712'),('t_cal','p_calok','M638 275H712'),('p_configok','t_join','M768 86C815 86 798 167 841 171'),('p_calok','t_join','M768 275C810 275 797 196 841 188'),('t_join','p_ready','M859 180H925'),('t_load','p_cell','M215 207V353H35V275H 48')]
 s='<svg id="cpn" xmlns="http://www.w3.org/2000/svg" width="1030" height="390" viewBox="0 0 1030 390" style="font-family:Microsoft YaHei,Noto Sans CJK SC,Arial,sans-serif"><defs><pattern id="g" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".8" fill="#cfdbe4"/></pattern><marker id="a" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M1 1L9 5L1 9" fill="none" stroke="#708799" stroke-width="1.6"/></marker></defs><rect width="1030" height="390" fill="#f6f8fa"/><rect width="1030" height="390" fill="url(#g)"/>'
 for a,b,d in arcs:s+=f'<path data-cpn-source="{a}" data-cpn-target="{b}" d="{d}" fill="none" stroke="#8296a6" stroke-width="2" marker-end="url(#a)"/>'
 for id,x,y,l,c,token in ps:
  s+=f'<g id="{id}" data-cpn-kind="place"><circle cx="{x}" cy="{y}" r="27" fill="white" stroke="{c}" stroke-width="2.4"/>'
  if token:s+=f'<circle cx="{x}" cy="{y}" r="7" fill="{c}"/>'
  s+=f'<text x="{x}" y="{y+50}" text-anchor="middle" fill="#3e5669" font-size="16" font-weight="500">{l}</text></g>'
 for id,x,y,l in ts:
  if id=='t_cal':s+=f'<rect x="{x-14}" y="{y-12}" width="46" height="78" rx="7" fill="#eef0fd" stroke="#a4a6cf" stroke-dasharray="4 3"/>'
  s+=f'<g id="{id}" data-cpn-kind="transition"><rect x="{x}" y="{y}" width="18" height="54" rx="2" fill="#8584b9"/><text x="{x+9}" y="{y-34 if id=='t_cal' else y-21}" text-anchor="middle" fill="#6e658f" font-size="16" font-weight="500">{l}</text></g>'
 s+='<text x="76" y="376" fill="#8b9bab" font-size="13">设备绑定保持</text><text x="455" y="50" fill="#91a0ab" font-family="Consolas" font-size="12">identity: J01 / ID 20</text><text x="545" y="362" fill="#aa854c" font-family="Consolas" font-size="12">recheck: J01 / missing</text><text x="894" y="335" fill="#8a809f" font-family="Consolas" font-size="12" text-anchor="middle">[identity_ok ∧ recheck_ok]</text></svg>'
 ET.fromstring(s);return s



def compile_page():
 center='<main class="center">'+tabs(['EG 编辑器','监督样例','编译产物'],tools=button('校验任务图','primary'))+'<div class="graph-canvas"><div class="graph-legend"><span>◯ Place / 状态</span><span>▮ Transition / 动作</span><span>● Typed token</span><span class="push"></span>'+tag('J01 复检记录缺失','amber')+'</div>'+cpn()+'<div class="canvas-bottom"><span>＋ 添加库所　 ▮ 添加变迁　 ↗ 连接</span><span>100%　−　＋</span></div></div><div class="training-drawer"><div class="drawer-title"><b>同一任务生成不同监督</b><span class="push"></span><small>观察、动作与验证结果保持关联</small></div><div class="sample-strip"><div><i class="green-dot"></i><b>身份识别</b><small>目标关节 + 软件反馈 → 核对身份</small></div><div><i class="amber-dot"></i><b>证据不足</b><small>复检记录缺失 → 请求补充证据</small></div><div><i class="purple-dot"></i><b>推进判定</b><small>身份 + 复检 + 设备绑定 → Guard</small></div></div></div></main>'
 inspect='<aside class="inspector"><div class="panel-heading">变迁属性<span>•••</span></div>'+tabs(['绑定','Guard','样例'],1)+'<div class="inspector-body"><div class="eyebrow">T04 / RECHECK REVIEW</div><h2>核验身份与复检证据</h2>'+tag('证据未齐 · 保持当前状态','amber')+'<div class="rule"></div>'+row('当前设备','MD-01')+row('目标关节','J01 / left_hip_yaw')+row('任务步骤','S03 / 软件识别与复检')+row('复检证据','缺失 / 保持待核验','amber-text')+'<div class="code"><span>guard</span><br>identity.bound_to(MD-01, J01)<br>&amp;&amp; identity.reviewed<br>&amp;&amp; recheck.bound_to(MD-01, J01)<br>&amp;&amp; recheck.reviewed</div><div class="guard-message">图像提供目标定位线索；软件身份和复检记录共同齐备后，Guard 才允许推进。</div><h4>编译产物</h4><div class="state-chip">任务 / EG · 监督数据 · 回放约束</div><p class="subtle">模型资产经过训练与独立评测后发布。</p></div></aside>'
 return app('compile',tree('compile')+center+inspect)
def simulate():
    toolbar='<div class="sim-command"><span class="run-id">INSTALL / MD-01</span><span class="run-status" id="run-status"><i></i> PAUSED</span><span class="sim-command-divider"></span>'+button('▶ <span class="play-label">播放步骤</span>','sim-play','play')+button('下一步','','step')+button('↶ 上一步','','replay')+button('重置','','reset')+'<span class="push"></span><span class="view-label">VIEW</span>'+button('定位安装面','','highlight')+button('组件展开','','explode')+button('旋转','','orbit')+'</div>'
    layers='<div class="scene-layers"><div>安装对象 <span>◉</span></div><button data-select="MD-01"><i class="layer-solid"></i>Microduck 主体</button><button data-select="HEAD-01"><i class="layer-wire"></i>头部与颈部</button><button data-select="J01"><i class="layer-anomaly"></i>髋部安装区域 <small>J01</small></button><button data-select="JOINTS-01"><i class="layer-grey"></i>腿部组件</button></div>'
    hud='<div class="sim-viewport-title"><b>INSTALLATION</b><span>Microduck · 安装过程</span><small id="view-mode">安装步骤示意</small></div><div class="sim-view-corner"><b>Y</b><i></i><span>X</span><em>Z</em></div><div class="sim-viewport-bottom"><span>拖动旋转 / 滚轮缩放 / 选择组件</span><span>DISPLAY SIMULATION</span></div><div class="sim-view-label"><small>当前步骤</small><b data-stage>2</b><span id="stage-description">抬升组件，对齐安装面</span></div>'
    viewport='<div class="stage3d simulation-view installation-simulation" data-mode="simulate">'+hud+layers+'</div>'
    previews=''.join('<div class="step-preview"><canvas data-preview="'+kind+'"></canvas><span data-preview-label="'+kind+'">'+label+'</span></div>' for kind,label in [('before','上一步'),('current','当前'),('after','下一步')])
    console='<aside class="sim-console installation-console"><div class="sim-console-tabs"><b>安装指导</b><span>步骤</span><span>观察</span></div><div class="sim-context"><span id="checkpoint-title">步骤 2 / 5</span><small id="selected-feature">J01</small></div><h2 id="operation-title">对齐髋部支架</h2><div class="operation-card"><b id="operation-instruction">抬升组件，对齐安装面</b><p id="operation-detail">将组件移向提示的安装位置，对照连接面方向。</p></div><div class="preview-heading">前一步 / 当前 / 下一步</div><div class="step-previews">'+previews+'</div><div class="branch-heading">对齐状态 <span id="branch-label">A / 按安装方向靠拢</span></div><div class="branch-options"><button data-act="baseline" class="branch-card active" id="baseline-card"><b>A</b><span>继续对齐<small>查看当前安装位置</small></span></button><button data-act="fork" class="branch-card" id="candidate-card"><b>B</b><span>重新定位<small>显示偏离后调整</small></span></button></div><div class="sim-checks"><div><i>✓</i>MD-01 / S03 / J01 已关联</div><div class="pending"><i>○</i>身份：<span id="identity-status">待核对</span></div><div class="pending"><i>○</i>复检：<span id="recheck-status">待补充，保持当前任务</span></div></div><p class="sim-limit">安装过程为显示示意，结果需提交检查记录</p></aside>'
    steps=[('准备部件','组件分离'),('对齐髋部支架','抬升并对齐'),('安装舵机与连接件','沿安装方向靠拢'),('固定与连接','检查连接位置'),('复检待完成','提交检查记录')]
    strip=''.join(f'<button class="installation-step" data-stage-select="{i}"><i>{i:02}</i><span><b>{name}</b><small>{hint}</small></span></button>' for i,(name,hint) in enumerate(steps,1))
    timeline='<div class="sim-timeline installation-timeline"><div class="replay-heading"><b>安装步骤</b><span class="push"></span><small>MD-SERVO-CHECK-01 / S03</small><span class="timecode" id="sim-frame">STEP 02 / 05</span></div><div class="installation-step-strip">'+strip+'</div><input id="stage-slider" aria-label="安装步骤" type="range" min="1" max="5" value="2" step="1"><div id="event-line">#0　步骤 2 · 抬升组件，对齐安装面</div></div>'
    body=f'<div class="app simulator-app">{header("simulate")}<div class="sim-workspace">{toolbar}<div class="sim-world">{viewport}{console}</div>{timeline}</div>{footer()}</div>'
    return doc(body,'simulate')

def mobile():
 return doc(f'''<div class="mobile mobile-microduck mobile-installation" data-assembly-state="in-progress" data-verification-state="missing"><div class="installation-observation"><img class="ar-background" alt="Microduck 髋部支架与舵机安装进行中的教学场景" src="{ASSET}installation-process.png"></div><div class="ar-shade"></div><div class="mobile-status"><span>09:41</span><span>▂▄▆　▰</span></div><div class="ar-head"><b>PSOP</b><span>FIELD ASSIST</span><button>×</button></div><div class="ar-task"><small>MD-SERVO-CHECK-01 / S03 安装与复检</small><b>03　安装进行中</b><p class="installation-instruction">对齐髋部连接支架<br><span>固定后复检</span></p><div><span>MD-01 · 目标安装区域 J01</span><span>3 / 5</span></div><div class="ar-progress"><i></i></div></div><div class="voice-card"><div class="voice-caption"><span class="voice-wave">▂▅▃▆▃▅▂</span><span>现场语音 · 转写示例</span></div><p>“先 <mark>对齐支架</mark>，固定后再 <mark>复检</mark>。”</p></div><div class="ar-view-label">{ico('camera')} 安装过程生成示意</div><div class="installation-target"><span>J01 · 安装区域</span><i class="installation-fastener"></i><div>支架对齐位置<small>固定后提交检查记录</small></div></div><div class="measurement-card"><div><small>身份信息</small><b>待核对</b></div><div><small>复检记录</small><b class="warm">待补充</b></div><p>安装完成后提交检查记录</p></div><div class="ar-bottom"><div class="ar-alert"><span>!</span><div><b>固定完成后，再核对安装结果</b><small>当前仍在安装，复检记录待补充</small></div></div><div class="ar-actions"><button>{ico('camera')}记录安装观察</button><button class="primary">{ico('file')}查看复检要求</button></div><div class="home-indicator"></div></div></div>''','mobile')

def main():
 pages={'build':build(),'compile':compile_page(),'simulate':simulate(),'mobile':mobile()}
 OUT.mkdir(parents=True,exist_ok=True)
